package glitch

import data.glitch_lib

# Insecure protocols pattern (without TLS/SSL)
insecure_protocols := {"http://", "ftp://", "telnet://", "smtp://", "ldap://"}

# Insecure flags that should be set to true for security
secure_flags := {"ssl_enabled", "use_ssl", "force_https", "secure_connection", "enable_https_traffic_only"}

# Check if a string contains an insecure protocol
contains_insecure_protocol(str) {
    some protocol
    insecure_protocols[protocol]
    contains(str, protocol)
}

# Check if a value (String, Sum, etc.) contains insecure protocol
check_value_for_protocol(value) {
    value.ir_type == "String"
    contains_insecure_protocol(value.value)
} else {
    value.ir_type == "Sum"
    check_value_for_protocol(value.left)
} else {
    value.ir_type == "Sum"
    check_value_for_protocol(value.right)
}

# Check if an attribute sets a secure flag to false or insecure value
check_insecure_flag(attr) {
    secure_flags[attr.name]
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    secure_flags[attr.name]
    attr.value.ir_type == "String"
    contains(attr.value.value, "(?i)no|false|0")
}

# Main detection rule for insecure protocols in attributes/variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for insecure protocols in attribute values
    check_value_for_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Using insecure protocol without encryption (CWE-319)"
    }
}

# Detection rule for insecure flags set to false
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    check_insecure_flag(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Insecure flag configuration - Security flags set to disable encryption (CWE-319)"
    }
}

# Detection rule for variables containing insecure protocols
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    check_value_for_protocol(var.value)

    result := {
        "type": "sec_https",
        "element": var,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Variable contains insecure protocol (CWE-319)"
    }
}

# Detection rule for function calls with insecure URLs (e.g., get_url, remote_file)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Common IaC functions that fetch resources
    insecure_functions := {"get_url", "remote_file", "file", "script"}
    contains(node.type, insecure_functions[_])

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check common attribute names for URLs
    url_attributes := {"url", "source", "path"}
    contains(url_attributes[_], attr.name)

    check_value_for_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Insecure URL in resource fetching (CWE-319)"
    }
}
